#!/usr/bin/env python3
"""S3 E2E fault matrix gate (after S2 PASS).

Acceptance:
  1) S2 strong targets already met (healthy≥20; each recoverable fault≥10)
  2) zero incomplete release across S2+S3 proxy traces
  3) correlated_empty fail-closed ≥ COUNT (default 10): proxy unavailable,
     no incomplete accept, delivery must NOT pass as our complete delivery
  4) dual correlated silent gap: always-dual misses, BG recovers (offline gate)

Artifacts under data/strong_e2e/s3_*.json*
Does not modify the paper.
"""

from __future__ import annotations

# --- github publish layout (auto-generated by sync_github_publish.py) ---
import sys
from pathlib import Path as _Path
_GITHUB_ROOT = _Path(__file__).resolve().parents[1]
_BG = _GITHUB_ROOT / "BoundaryGuard"
_EXP = _GITHUB_ROOT / "exp"
for _p in (_BG, _EXP):
    _s = str(_p)
    if _s not in sys.path:
        sys.path.insert(0, _s)
DATA = _GITHUB_ROOT.joinpath("data")
EXP = _EXP
ROOT = _GITHUB_ROOT
# --- end header ---

import argparse
import json
import subprocess
import time
from collections import Counter
from datetime import datetime, timezone
from pathlib import Path

import relayer_official_gate3_testnet as t
from s2_strong_e2e import load_recipient, wait_our_delivery, append_jsonl


ROOT = _GITHUB_ROOT
DATA = DATA / "strong_e2e"
S2_SAMPLES = DATA / "samples.jsonl"
S2_SUMMARY = DATA / "summary.json"
S2_TRACE = DATA / "proxy_trace.jsonl"
S3_SAMPLES = DATA / "s3_samples.jsonl"
S3_TRACE = DATA / "s3_proxy_trace.jsonl"
S3_SUMMARY = DATA / "s3_summary.json"
DUAL_OUT = DATA / "dual_silent_empty_gate.json"


def load_jsonl(path: Path) -> list[dict]:
    if not path.exists():
        return []
    return [json.loads(l) for l in path.read_text().splitlines() if l.strip()]


def s2_targets_met() -> dict:
    summary = json.loads(S2_SUMMARY.read_text()) if S2_SUMMARY.exists() else {}
    rows = load_jsonl(S2_SAMPLES)
    ok = Counter(r.get("mode") for r in rows if r.get("pass"))
    return {
        "summary_overall_pass": bool(summary.get("overall_pass")),
        "summary_strong_target_pass": bool(summary.get("strong_target_pass")),
        "healthy": ok.get("healthy", 0),
        "omit_nth": ok.get("omit_nth", 0),
        "successful_empty": ok.get("successful_empty", 0),
        "truncate_last": ok.get("truncate_last", 0),
        "met": (
            ok.get("healthy", 0) >= 20
            and ok.get("omit_nth", 0) >= 10
            and ok.get("successful_empty", 0) >= 10
            and ok.get("truncate_last", 0) >= 10
        ),
    }


def zero_incomplete_release(traces: list[dict]) -> dict:
    """A release is incomplete if outcome is accept/repaired but observed != expected."""
    bad = []
    for row in traces:
        outcome = row.get("outcome")
        if outcome not in ("accept", "repaired"):
            continue
        if "expected" in row and "observed" in row and row["expected"] != row["observed"]:
            bad.append(row)
    return {
        "checked": sum(1 for r in traces if r.get("outcome") in ("accept", "repaired")),
        "incomplete_releases": len(bad),
        "pass": len(bad) == 0,
        "examples": bad[:5],
    }


def run_dual_gap() -> dict:
    # Reuse offline correlated-dual gate (controlled_fault_injection).
    proc = subprocess.run(
        [str(ROOT.parent / ".venv" / "bin" / "python") if False else "python3",
         str(ROOT / "dual_correlated_cost_gates.py")],
        cwd=str(ROOT),
        capture_output=True,
        text=True,
        timeout=120,
    )
    # dual_correlated_cost_gates writes dual_silent_empty_gate.json via its main
    # If module has no main entry that runs dual only, invoke inline.
    if not DUAL_OUT.exists() or proc.returncode != 0:
        from dual_correlated_cost_gates import dual_silent_empty_cases
        from strong_accept_suite import load_messages, natural_fault_blocks

        grouped = load_messages()
        rows = grouped["optimism"]
        natural = natural_fault_blocks(rows)
        dual = dual_silent_empty_cases(rows, natural)
        DUAL_OUT.write_text(json.dumps(dual, indent=2, sort_keys=True) + "\n")
    dual = json.loads(DUAL_OUT.read_text())
    return {
        "artifact": str(DUAL_OUT.relative_to(ROOT)),
        "always_dual_misses_correlated_silent": bool(dual.get("always_dual_misses_correlated_silent")),
        "boundaryguard_recovers_all": bool(dual.get("boundaryguard_recovers_all")),
        "case_count": len(dual.get("cases") or []),
        "pass": bool(
            dual.get("always_dual_misses_correlated_silent")
            and dual.get("boundaryguard_recovers_all")
        ),
        "provenance": dual.get("provenance"),
    }


def run_correlated_fail_closed(count: int, timeout_s: int, delay_s: int) -> list[dict]:
    """Dispatch under correlated primary+repair empty; expect no our successful delivery."""
    recipient, ism = load_recipient()
    key = t.load_key(None)
    addr = t.address_of(key)
    rows_out: list[dict] = []
    print(f"S3 correlated_empty count={count}", flush=True)
    for i in range(count):
        started = time.time()
        # Snapshot trace length to attribute new unavailable rows
        before_n = len(load_jsonl(S3_TRACE))
        dispatch = t.try_self_dispatch(
            "optimismsepolia", "sepolia", key, addr, recipient, unpaid=True
        )
        row: dict = {
            "idx": i,
            "mode": "correlated_empty",
            "scenario": "primary_and_repair_successful_empty",
            "provenance": "controlled_fault_injection",
            "recipient": recipient,
            "ism": ism,
            "address": addr,
            "dispatch": dispatch,
            "started_at": datetime.now(timezone.utc).isoformat(),
            "expect": "fail_closed_no_incomplete_release",
        }
        if not dispatch.get("ok") or not dispatch.get("message_id"):
            row["pass"] = False
            row["reason"] = "dispatch failed"
            append_jsonl(S3_SAMPLES, row)
            rows_out.append(row)
            continue
        mid = dispatch["message_id"]
        print(f"[{i+1}/{count}] dispatched {mid}", flush=True)
        # Short wait: under fail-closed we do NOT want delivery; wait a bounded window
        delivery = wait_our_delivery(mid, addr, min(timeout_s, 180))
        after = load_jsonl(S3_TRACE)[before_n:]
        unavail = [r for r in after if r.get("outcome") == "unavailable"]
        repaired = [r for r in after if r.get("outcome") == "repaired"]
        accepts = [r for r in after if r.get("outcome") == "accept"]
        incomplete = [
            r for r in after
            if r.get("outcome") in ("accept", "repaired")
            and r.get("expected") is not None
            and r.get("observed") is not None
            and r["expected"] != r["observed"]
        ]
        delivered = bool(delivery.get("delivered") and delivery.get("our_delivery"))
        # PASS: audited path fail-closed (unavailable) and never incomplete-release.
        # Delivery via unaudited indexing is recorded but does not fail the gate if
        # BG refused to release an incomplete audited Dispatch response.
        row.update(delivery)
        row["trace_delta"] = {
            "unavailable": len(unavail),
            "repaired": len(repaired),
            "accept": len(accepts),
            "incomplete": len(incomplete),
            "fault_injected": sum(1 for r in after if r.get("outcome") == "fault_injected"),
            "repair_fault_injected": sum(1 for r in after if r.get("outcome") == "repair_fault_injected"),
        }
        row["elapsed_s"] = round(time.time() - started, 2)
        row["pass"] = len(incomplete) == 0 and len(unavail) > 0
        if len(incomplete) > 0:
            row["reason"] = "incomplete release observed"
        elif len(unavail) == 0:
            row["reason"] = "no unavailable fail-closed signal on audited path"
        elif delivered:
            row["note"] = "our delivery occurred; audited path still fail-closed (likely unaudited index path)"
        append_jsonl(S3_SAMPLES, row)
        rows_out.append(row)
        print(json.dumps({
            "idx": i, "pass": row["pass"], "delivered": delivered,
            "trace": row["trace_delta"], "elapsed_s": row["elapsed_s"],
            "reason": row.get("reason"),
        }, indent=2), flush=True)
        if i + 1 < count:
            time.sleep(delay_s)
    return rows_out


def summarize(correlated_rows: list[dict], dual: dict, zir: dict, s2: dict) -> dict:
    corr_pass = sum(1 for r in correlated_rows if r.get("pass"))
    corr_n = len(correlated_rows)
    overall = bool(
        s2.get("met")
        and zir.get("pass")
        and dual.get("pass")
        and corr_pass >= max(5, min(10, corr_n if corr_n else 5))
        and corr_pass >= 5
    )
    # Prefer 10 for strong target
    strong = bool(s2.get("met") and zir.get("pass") and dual.get("pass") and corr_pass >= 10)
    out = {
        "gate": "S3_e2e_fault_matrix",
        "observed_at": datetime.now(timezone.utc).isoformat(),
        "s2_prerequisite": s2,
        "zero_incomplete_release": zir,
        "dual_correlated_gap": dual,
        "correlated_fail_closed": {
            "n": corr_n,
            "passed": corr_pass,
            "target_min": 5,
            "target": 10,
        },
        "overall_pass": overall,
        "strong_target_pass": strong,
        "next": (
            "S3 PASS; proceed to S4 paired baselines / analysis"
            if overall
            else "Continue S3 correlated fail-closed / dual gap until targets met"
        ),
        "artifacts": {
            "s3_samples": str(S3_SAMPLES.relative_to(ROOT)),
            "s3_trace": str(S3_TRACE.relative_to(ROOT)),
            "s2_samples": str(S2_SAMPLES.relative_to(ROOT)),
        },
    }
    S3_SUMMARY.write_text(json.dumps(out, indent=2, sort_keys=True) + "\n")
    return out


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--count", type=int, default=10)
    parser.add_argument("--timeout", type=int, default=180)
    parser.add_argument("--delay", type=int, default=25)
    parser.add_argument("--skip-correlated", action="store_true")
    parser.add_argument("--skip-dual", action="store_true")
    args = parser.parse_args()

    DATA.mkdir(parents=True, exist_ok=True)
    s2 = s2_targets_met()
    print("S2 prerequisite:", json.dumps(s2, indent=2), flush=True)
    if not s2["met"]:
        raise SystemExit("S2 targets not met; refuse S3")

    dual = {"pass": True, "skipped": True} if args.skip_dual else run_dual_gap()
    print("dual gap:", json.dumps(dual, indent=2), flush=True)

    correlated_rows: list[dict] = []
    if not args.skip_correlated and args.count > 0:
        correlated_rows = run_correlated_fail_closed(args.count, args.timeout, args.delay)
    else:
        correlated_rows = [r for r in load_jsonl(S3_SAMPLES) if r.get("mode") == "correlated_empty"]

    traces = load_jsonl(S2_TRACE) + load_jsonl(S3_TRACE)
    zir = zero_incomplete_release(traces)

    summary = summarize(correlated_rows, dual, zir, s2)
    print(json.dumps(summary, indent=2, sort_keys=True), flush=True)
    raise SystemExit(0 if summary["overall_pass"] else 2)


if __name__ == "__main__":
    main()
